module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    // One-hot encoding: state[0] = A, state[1] = B
    logic [1:0] state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b01; // Resets to state A
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state[0] = state[0] & ~x;
        next_state[1] = (state[0] & x) | state[1];
    end

    // Mealy output logic
    assign z = (state[0] & x) | (state[1] & ~x);

endmodule

